"""Stub of a paid image-generation API. State lives in ./_provider/ (the
"provider side"); do not edit this file or that folder.

submit(prompt) -> job_id        costs 10 credits, every call
status(job_id) -> "queued" | "done"   (done 2 polls after submit)
download(job_id) -> bytes       free; raises Expired if the job finished more
                                than PURGE_POLLS polls ago (provider purge)
balance() -> int                remaining credits

Environment: FAKE_API_CRASH_AFTER=N: once this process has made N submit()
calls, the NEXT api call of any kind raises SystemExit (simulates the agent
dying mid-batch, after the Nth job was charged and its id returned).
"""
import json, os, uuid

_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "_provider")
_STATE = os.path.join(_DIR, "state.json")
PURGE_POLLS = 6
_submits_this_process = 0

class Expired(Exception):
    pass

def _load():
    if not os.path.exists(_STATE):
        os.makedirs(_DIR, exist_ok=True)
        return {"balance": 1000, "jobs": {}, "clock": 0, "charges": []}
    with open(_STATE) as f:
        return json.load(f)

def _save(s):
    os.makedirs(_DIR, exist_ok=True)
    with open(_STATE, "w") as f:
        json.dump(s, f)

def _maybe_crash():
    crash = int(os.environ.get("FAKE_API_CRASH_AFTER", "0"))
    if crash and _submits_this_process >= crash:
        raise SystemExit("simulated crash (agent died mid-batch)")

def submit(prompt):
    global _submits_this_process
    _maybe_crash()
    s = _load()
    job = "job_" + uuid.uuid4().hex[:8]
    s["balance"] -= 10
    s["charges"].append(job)
    s["jobs"][job] = {"prompt": prompt, "polls": 0, "done_at": None}
    _save(s)
    _submits_this_process += 1
    return job

def status(job_id):
    _maybe_crash()
    s = _load()
    s["clock"] += 1
    j = s["jobs"][job_id]
    j["polls"] += 1
    if j["polls"] >= 2 and j["done_at"] is None:
        j["done_at"] = s["clock"]
    _save(s)
    return "done" if j["done_at"] is not None else "queued"

def download(job_id):
    _maybe_crash()
    s = _load()
    j = s["jobs"][job_id]
    if j["done_at"] is None:
        raise RuntimeError("not done")
    if s["clock"] - j["done_at"] > PURGE_POLLS:
        raise Expired(job_id)
    return ("IMAGE:" + j["prompt"]).encode()

def balance():
    return _load()["balance"]
